function _dispatch(req, url, env) {
  const segments = url.pathname.slice(1).split('/').filter(Boolean)
  const method = req.method
  const params = {}
    const seg0 = segments[0]
  switch (seg0) {
    case 'auth': {
      const seg1 = segments[1]
      switch (seg1) {
        case 'github': {
          }
            switch (method) {
              case 'GET': return _route_get_auth_github(req, params, env)
              default: return new Response('Method Not Allowed', { status: 405 })
            }
          if (segments.length === 2) {
          const seg2 = segments[2]
          switch (seg2) {
            case 'callback': {
              switch (method) {
                case 'GET': return _route_get_auth_github_callback(req, params, env)
                default: return new Response('Method Not Allowed', { status: 405 })
              }
            }
            default: return new Response('Not Found', { status: 404 })
          }
        }
        case 'logout': {
          switch (method) {
            case 'POST': return _route_post_auth_logout(req, params, env)
            default: return new Response('Method Not Allowed', { status: 405 })
          }
        }
        case 'me': {
          switch (method) {
            case 'GET': return _route_get_auth_me(req, params, env)
            default: return new Response('Method Not Allowed', { status: 405 })
          }
        }
        case 'profile': {
          switch (method) {
            case 'GET': return _route_get_auth_profile(req, params, env)
            default: return new Response('Method Not Allowed', { status: 405 })
          }
        }
        default: return new Response('Not Found', { status: 404 })
      }
    }
    case 'posts': {
      }
        switch (method) {
          case 'GET': return _route_get_posts(req, params, env)
          case 'POST': return _route_post_posts(req, params, env)
          default: return new Response('Method Not Allowed', { status: 405 })
        }
      if (segments.length === 1) {
      params['id'] = segments[1]
      switch (method) {
        case 'GET': return _route_get_posts__id(req, params, env)
        case 'DEL': return _route_del_posts__id(req, params, env)
        default: return new Response('Method Not Allowed', { status: 405 })
      }
    }
    case 'health': {
      switch (method) {
        case 'GET': return _route_get_health(req, params, env)
        default: return new Response('Method Not Allowed', { status: 405 })
      }
    }
    default: return new Response('Not Found', { status: 404 })
  }
  return new Response('Not Found', { status: 404 })
}

const _jobRegistry = {
  'NotifySubscribers': _job_NotifySubscribers,
}

export default {
  async fetch(req, env, ctx) {
    const url = new URL(req.url)
    return _dispatch(req, url, env)
  },
  async queue(batch, env) {
    for (const msg of batch.messages) {
      const { job, args = [] } = msg.body
      const fn = _jobRegistry[job]
      if (fn) {
        try { await fn(...args, env) } catch (e) { console.error('[arc:queue]', e) }
      }
      msg.ack()
    }
  },
}